DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260601090000_AddAccountActiveFrom') THEN
    ALTER TABLE "Accounts" ADD "ActiveFromUtc" timestamp with time zone;
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260601090000_AddAccountActiveFrom') THEN
    UPDATE "Accounts" AS account
    SET "ActiveFromUtc" = restore."ChangedAtUtc"
    FROM (
        SELECT "EntityId", MAX("ChangedAtUtc") AS "ChangedAtUtc"
        FROM "AuditLogs"
        WHERE "EntityType" = 'Account'
          AND "Operation" = 'Update'
          AND COALESCE("OldValuesJson" ->> 'IsArchived', "OldValuesJson" ->> 'isArchived') = 'true'
          AND COALESCE("NewValuesJson" ->> 'IsArchived', "NewValuesJson" ->> 'isArchived') = 'false'
        GROUP BY "EntityId"
    ) AS restore
    WHERE account."Id" = restore."EntityId"
      AND account."IsArchived" = false
      AND account."ActiveFromUtc" IS NULL;
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260601090000_AddAccountActiveFrom') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20260601090000_AddAccountActiveFrom', '10.0.7');
    END IF;
END $EF$;
COMMIT;

