    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260623055248_AddLoanPrepayments') THEN
    CREATE TABLE "LoanPrepayments" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "LoanId" integer NOT NULL,
        "PrepaymentDate" date NOT NULL,
        "Amount" numeric NOT NULL,
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "UpdatedAtUtc" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_LoanPrepayments" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_LoanPrepayments_Loans_LoanId" FOREIGN KEY ("LoanId") REFERENCES "Loans" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260623055248_AddLoanPrepayments') THEN
    CREATE INDEX "IX_LoanPrepayments_LoanId_PrepaymentDate" ON "LoanPrepayments" ("LoanId", "PrepaymentDate");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260623055248_AddLoanPrepayments') THEN
    INSERT INTO "LoanPrepayments" ("LoanId", "PrepaymentDate", "Amount", "CreatedAtUtc", "UpdatedAtUtc")
    SELECT
        matched."LoanId",
        make_date(matched."Year", matched."Month", 1),
        matched."ActualAmount",
        NOW(),
        NOW()
    FROM (
        SELECT
            e."Id" AS "ExpenseId",
            MAX(l."Id") AS "LoanId",
            mp."Year",
            mp."Month",
            e."ActualAmount",
            COUNT(*) AS "MatchCount"
        FROM "Expenses" e
        INNER JOIN "MonthPlans" mp
            ON mp."Id" = e."MonthPlanId"
            AND mp."UserId" = e."UserId"
        INNER JOIN "Categories" c
            ON c."Id" = e."CategoryId"
            AND c."Name" = 'Kredyt'
        INNER JOIN "Loans" l
            ON l."UserId" = e."UserId"
            AND l."Name" = left(e."Name", length(e."Name") - length(' - nadpłata'))
            AND (
                (l."TagId" IS NULL AND e."TagId" IS NULL)
                OR l."TagId" = e."TagId"
            )
        WHERE e."LoanInstallmentId" IS NULL
            AND e."RegularExpenseDefinitionId" IS NULL
            AND e."ActualAmount" > 0
            AND e."PlannedAmount" = 0
            AND e."ShowRemainingInUI" = TRUE
            AND e."Name" LIKE '% - nadpłata'
            AND e."IsDeleted" = FALSE
        GROUP BY e."Id", mp."Year", mp."Month", e."ActualAmount"
    ) matched
    WHERE matched."MatchCount" = 1;
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260623055248_AddLoanPrepayments') THEN
    INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
    VALUES ('20260623055248_AddLoanPrepayments', '10.0.7');
    END IF;
END $EF$;
COMMIT;

START TRANSACTION;

DO $EF$
BEGIN
