    CREATE TABLE "LoanOperationAudits" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "LoanId" integer NOT NULL,
        "UserId" character varying(128) NOT NULL,
        "BudgetOwnerUserId" character varying(128) NOT NULL,
        "OperationType" character varying(64) NOT NULL,
        "Status" character varying(32) NOT NULL,
        "OccurredAtUtc" timestamp with time zone NOT NULL,
        "ScheduleVersionBefore" character varying(128) NOT NULL,
        "ScheduleVersionAfter" character varying(128) NOT NULL,
        "OperationPayloadJson" jsonb NOT NULL,
        "RevertedAtUtc" timestamp with time zone,
        "RevertedByUserId" character varying(128),
        "RevertsOperationId" integer,
        "RevertedByOperationId" integer,
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "UpdatedAtUtc" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_LoanOperationAudits" PRIMARY KEY ("Id"),
